/** The guide as Markdown (docs/USER_GUIDE.md is generated from it). */
export function guideToMarkdown(): string {
  const out: string[] = [
    '# pixels user guide',
    '',
    'Generated from `apps/web/src/help/guide.ts`. Do not edit by hand.',
    '',
  ]
  out.push('## Contents', '')
  for (const s of GUIDE) out.push(`- [${s.title}](#${s.id})`)
  out.push('')
  for (const s of GUIDE) {
    out.push(`<a id="${s.id}"></a>`, '', `## ${s.title}`, '', `*${s.summary}*`, '')
    for (const b of s.blocks) {
      if ('p' in b) out.push(b.p, '')
      else if ('ul' in b) out.push(...b.ul.map((x) => `- ${x}`), '')
      else if ('steps' in b) out.push(...b.steps.map((x, i) => `${i + 1}. ${x}`), '')
      else if ('tip' in b) out.push(`> **Tip:** ${b.tip}`, '')
      else
        out.push(
          '| Keys | What it does |',
          '| --- | --- |',
          ...b.keys.map(([k, d]) => `| ${k.replaceAll('|', '\\|')} | ${d} |`),
          '',
        )
    }
  }
  return out.join('\n')
}
